import java.util.*;
public class Main {
 public static void main(String[] args) {
  Scanner in=new Scanner(System.in); TreeMap<Integer,Integer> counts=new TreeMap<>();
  while(in.hasNextInt()){int n=in.nextInt();counts.merge(n,1,Integer::sum);}
  StringJoiner out=new StringJoiner(" ");
  for(var e:counts.entrySet())if(e.getValue()>1)out.add(e.getKey().toString());
  System.out.println(out.length()==0?"NONE":out.toString());
 }
}
